/* Region tabs + a centre-focused, rotating brand carousel.
   The platform `carousel` behaviour is a scroll-snap rail, which cannot hold a card in a
   fixed centre or rotate a set past its ends, so this component runs its own stage. The
   rail never scrolls: every card sits in one grid cell and this script only sets
   `data-o` (the card's offset from the active one: -2 ... 2, or "far") — CSS turns that
   into a translateX + scale. Previous / Next change the active index, wrapping round, so
   no brand is skipped and the active card never leaves the centre. Without this script
   (and in the Design canvas, which runs none) the rail is an ordinary in-flow row. */
(function () {
  document.querySelectorAll('[data-bz-section="region-brands"]').forEach(function (root) {
    var rail = root.querySelector('[data-bz-node="rb-rail"]');
    if (!rail) return;
    var slides = [].slice.call(rail.querySelectorAll('[data-bz-node^="rb-slide"]'));
    var tabs = [].slice.call(root.querySelectorAll('[data-bz-node^="rb-tab-btn"] a'));
    var prevBtn = root.querySelector('[data-bz-node="rb-prev"] a');
    var nextBtn = root.querySelector('[data-bz-node="rb-next"] a');
    if (!slides.length) return;

    var REACH = 2;                       // cards drawn each side of the active one
    var shown = [];                      // the visible slides, in order, for the chosen region
    var active = 0;                      // index into `shown`
    var last = new Map();                // slide -> last offset, to spot wrap-around jumps

    function regionsOf(slide) {
      var n = slide.querySelector('[data-bz-node^="rb-regions"]');
      return (n ? n.textContent : '').toLowerCase().split(/[\s,]+/).filter(Boolean);
    }
    function keyOf(tab) { return (tab.getAttribute('href') || '').replace(/^#/, '').toLowerCase(); }

    // Shortest signed distance round the ring, so the card after the last is the first.
    function offsetOf(i) {
      var n = shown.length, d = (((i - active) % n) + n) % n;
      if (d > n / 2) d -= n;
      return d;
    }

    function render(instant) {
      if (instant) rail.classList.add('is-reset');
      var jumpers = [];
      shown.forEach(function (s, i) {
        var d = offsetOf(i), prev = last.get(s);
        var far = Math.abs(d) > REACH;
        s.setAttribute('data-o', far ? 'far' : String(d));
        var link = s.querySelector('[data-bz-node^="rb-view"] a');
        if (link) link.tabIndex = d === 0 ? 0 : -1;
        s.setAttribute('aria-current', d === 0 ? 'true' : 'false');
        // A card travelling more than one place is wrapping round the ring: hide it while it
        // crosses, then let it fade in at the far side instead of sweeping through the rest.
        if (!instant && prev !== undefined && !far && Math.abs(d - prev) > 1) jumpers.push(s);
        last.set(s, far ? 99 : d);
      });
      if (jumpers.length) {
        jumpers.forEach(function (s) { s.classList.add('is-jump'); });
        void rail.offsetWidth;
        requestAnimationFrame(function () {
          jumpers.forEach(function (s) { s.classList.remove('is-jump'); });
        });
      }
      if (instant) {
        void rail.offsetWidth;
        requestAnimationFrame(function () { rail.classList.remove('is-reset'); });
      }
    }

    function go(delta) {
      if (shown.length < 2) return;
      active = (((active + delta) % shown.length) + shown.length) % shown.length;
      render(false);
    }

    function select(key) {
      tabs.forEach(function (t) {
        var on = keyOf(t) === key;
        t.classList.toggle('is-active', on);
        t.setAttribute('aria-pressed', String(on));
      });
      slides.forEach(function (s) { s.hidden = key ? regionsOf(s).indexOf(key) < 0 : false; });
      shown = slides.filter(function (s) { return !s.hidden; });
      last.clear();
      active = Math.floor((shown.length - 1) / 2);   // the middle brand, as before
      render(true);
    }

    tabs.forEach(function (t) {
      t.addEventListener('click', function (e) { e.preventDefault(); select(keyOf(t)); });
    });
    [[prevBtn, -1], [nextBtn, 1]].forEach(function (p) {
      if (!p[0]) return;
      p[0].addEventListener('click', function (e) { e.preventDefault(); go(p[1]); });
    });
    // A side card steps toward the middle when it is chosen.
    slides.forEach(function (s) {
      s.addEventListener('click', function (e) {
        var o = s.getAttribute('data-o');
        if (e.target.closest('a') || o === '0' || o === 'far' || o === null) return;
        go(Number(o));
      });
    });
    // Keyboard and touch.
    rail.setAttribute('tabindex', '0');
    rail.setAttribute('role', 'group');
    rail.setAttribute('aria-roledescription', 'carousel');
    rail.setAttribute('aria-label', 'Brands');
    rail.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowRight') { e.preventDefault(); go(1); }
      if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); }
    });
    var x0 = null, y0 = null;
    rail.addEventListener('touchstart', function (e) {
      var t = e.touches[0]; x0 = t.clientX; y0 = t.clientY;
    }, { passive: true });
    rail.addEventListener('touchend', function (e) {
      if (x0 === null) return;
      var t = e.changedTouches[0], dx = t.clientX - x0, dy = t.clientY - y0;
      x0 = y0 = null;
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy) * 1.5) go(dx < 0 ? 1 : -1);
    }, { passive: true });

    rail.classList.add('is-staged');
    select(tabs[0] ? keyOf(tabs[0]) : '');
  });
})();
